SELECT 
FROM bible_books
WHERE version_id = #{versionId}
  AND book_code = #{bookCode}
  AND (

      (chapter = #{chapterFrom}
         AND verse >= #{verseFrom}
      )
      OR (chapter > #{chapterFrom} AND chapter < #{chapterTo})
      OR (chapter = #{chapterTo}
         AND verse <= #{verseTo}
      )


      chapter = #{chapterFrom}
       AND verse >= #{verseFrom}
       AND verse <= #{verseTo}

  )
ORDER BY chapter, verse

SELECT 
FROM bible_books
WHERE version_id = #{versionId}
  AND book_code = #{bookCode}
  AND chapter = #{chapter}
ORDER BY verse

SELECT 
FROM bible_books
WHERE version_id = #{versionId}
  AND book_name_kr = #{bookNameKr}
LIMIT 1
